1	/**
2	 * Which checkouts the host may run Git in. The agent's sandbox can write its worktree (its `.git` pointer and nested
3	 * repositories included) but nothing outside it, and Git reads the configuration of whatever repository `.git` leads
4	 * to, so a planted one is a way to run a command on the host. Pure file-system checks, shared by the worktree Git helper
5	 * (`worktrunk/git.ts`), the session's own Git helpers and the checkpoint manager; no dependency on any of them.
6	 */
7	import * as fs from "node:fs";
8	import * as path from "node:path";
9	
10	function inside(root: string, candidate: string): boolean {
11	  return candidate === root || candidate.startsWith(root + path.sep);
12	}
13	
14	/** Variables that change how Git reads pathspecs; an inherited one would turn a `:(top)` magic pathspec literal or case-insensitive. */
15	export const PATHSPEC_MODE_ENV: readonly string[] = ["GIT_LITERAL_PATHSPECS", "GIT_GLOB_PATHSPECS", "GIT_NOGLOB_PATHSPECS", "GIT_ICASE_PATHSPECS"];
16	
17	/**
18	 * The path in a `.git` pointer file, read the way Git reads it: the content must start with `gitdir: `, only the
19	 * trailing line break is dropped, and nothing else is trimmed. A guard that trimmed would resolve a different directory
20	 * than Git does for `gitdir: x ` and could be shown a harmless one; such a pointer is refused instead.
21	 */
22	export function parseGitfilePointer(content: string): string | undefined {
23	  if (!content.startsWith("gitdir: ")) return undefined;
24	  const target = content.slice("gitdir: ".length).replace(/\r?\n$/, "");
25	  if (target === "" || target !== target.trim() || /[\0\r\n]/.test(target)) return undefined;
26	  return target;
27	}
28	
29	/**
30	 * The text of a small regular file, or undefined. The agent controls these paths: a FIFO would block the host's
31	 * synchronous read for ever, a link to `/dev/zero` or a huge sparse file would exhaust memory. Nothing is opened unless
32	 * `lstat` says it is a plain file of at most `maxBytes`, and it is opened non-blocking without following links.
33	 */
34	export function readSmallFile(file: string, maxBytes: number): string | undefined {
35	  try {
36	    const stat = fs.lstatSync(file);
37	    if (stat.isSymbolicLink() || !stat.isFile() || stat.size > maxBytes) return undefined;
38	    const fd = fs.openSync(file, fs.constants.O_RDONLY | fs.constants.O_NONBLOCK | fs.constants.O_NOFOLLOW);
39	    try {
40	      const opened = fs.fstatSync(fd);
41	      if (!opened.isFile() || opened.size > maxBytes) return undefined;
42	      return fs.readFileSync(fd, "utf8");
43	    } finally { fs.closeSync(fd); }
44	  } catch { return undefined; }
45	}
46	
47	export const MAX_POINTER_BYTES = 4096;
48	const MAX_CONFIG_BYTES = 1024 * 1024;
49	
50	/** Repositories this process has opened and their linked worktrees (from `git worktree list`, run where the operator is). */
51	const knownCommonDirs = new Set<string>();
52	const knownLinkedWorktrees = new Set<string>();
53	export function rememberRepository(commonDir: string, linkedWorktrees: readonly string[]): void {
54	  knownCommonDirs.add(commonDir);
55	  for (const dir of linkedWorktrees) {
56	    try { knownLinkedWorktrees.add(fs.realpathSync(dir)); } catch { /* gone: nothing to run Git in */ }
57	  }
58	}
59	
60	/**
61	 * Whether `root`, which has a `.git` DIRECTORY, is really a linked worktree whose `.git` FILE the agent replaced: it is
62	 * a linked worktree of a repository this process opened, or it is registered (with its `.git` file) in an enclosing
63	 * repository's or an opened repository's worktree registry. A registry entry that cannot be read is skipped on its own,
64	 * never ending the scan of the others.
65	 */
66	export function replacedWorktreeReason(root: string): string | undefined {
67	  if (knownLinkedWorktrees.has(root)) return `${root} is a linked worktree whose .git file was replaced by a repository`;
68	  const registries = new Set<string>(Array.from(knownCommonDirs, (common) => path.join(common, "worktrees")));
69	  for (let dir = path.dirname(root); ; dir = path.dirname(dir)) {
70	    registries.add(path.join(dir, ".git", "worktrees"));
71	    if (path.dirname(dir) === dir) break;
72	  }
73	  // The sibling layout (`<repo>.<branch>` beside `<repo>`) puts the main repository next to the worktree, not above it.
74	  const parent = path.dirname(root);
75	  try {
76	    for (const child of fs.readdirSync(parent)) {
77	      if (path.basename(root).startsWith(child + ".")) registries.add(path.join(parent, child, ".git", "worktrees"));
78	    }
79	  } catch { /* unreadable */ }
80	  for (const registry of registries) {
81	    let names: string[];
82	    try { names = fs.readdirSync(registry); } catch { continue; } // no registry here
83	    for (const name of names) {
84	      try {
85	        const recorded = readSmallFile(path.join(registry, name, "gitdir"), MAX_POINTER_BYTES)?.trim();
86	        if (recorded === undefined) continue;
87	        if (path.basename(recorded) === ".git" && fs.realpathSync(path.dirname(path.resolve(registry, name, recorded))) === root) {
88	          return `${root} is a linked worktree registered in ${path.dirname(path.dirname(registry))} whose .git file was replaced by a repository`;
89	        }
90	      } catch { /* a stale entry (its directory was deleted by hand) */ }
91	    }
92	  }
93	  return undefined;
94	}
95	
96	/**
97	 * The agent runs in a sandbox that can write its worktree, `.git` pointer file and any nested repository included, but
98	 * nothing outside it. Git reads the configuration of whatever repository `.git` leads to; a planted one can carry
99	 * commands (`filter.*.clean`, `commit.gpgsign` with `gpg.program`) that would run on the host. A checkout is trusted only
100	 * when every `.git` file on the way up is a plain pointer to a Git directory OUTSIDE the outermost linked worktree
101	 * (outside what the agent can write) that points back at it (`gitdir` of a `<common>/worktrees/<name>` entry, or
102	 * `core.worktree` of a separate or submodule Git directory), and no repository with a real `.git` directory sits inside
103	 * a linked worktree. `gitDir`/`workTree` are the verified pair for the nearest `.git` file: Git is then run against them
104	 * directly, so a pointer rewritten after this check is not re-read.
105	 */
106	export function verifyCheckout(cwd: string): { reason?: string; gitDir?: string; workTree?: string } {
107	  let start: string;
108	  try { start = fs.realpathSync(cwd); } catch { return {}; }
109	  const files: string[] = [];
110	  const directories: string[] = [];
111	  for (let dir = start; ; dir = path.dirname(dir)) {
112	    try {
113	      if (fs.lstatSync(path.join(dir, ".git")).isDirectory()) directories.push(dir); else files.push(dir);
114	    } catch { /* no .git here */ }
115	    if (path.dirname(dir) === dir) break;
116	  }
117	  // The agent-writable boundary is the outermost LINKED worktree (its `.git` leads to `<common>/worktrees/<name>`). A
118	  // `.git` file above it (a bare-repository layout `project/.git` -> `.bare`) is the operator's, not the agent's.
119	  const isLinkedRoot = (root: string): boolean => {
120	    try {
121	      const content = readSmallFile(path.join(root, ".git"), MAX_POINTER_BYTES);
122	      const target = content === undefined ? undefined : parseGitfilePointer(content);
123	      return target !== undefined && path.basename(path.dirname(fs.realpathSync(path.resolve(root, target)))) === "worktrees";
124	    } catch { return false; }
125	  };
126	  const outer = [...files].reverse().find(isLinkedRoot) ?? files[files.length - 1];
127	  if (!outer) {
128	    // A plain repository (or none). But a registered linked worktree whose `.git` file the agent replaced by a repository
129	    // looks exactly like one: the main repository's worktree registry says it is not.
130	    for (const root of directories) {
131	      const replaced = replacedWorktreeReason(root);
132	      if (replaced) return { reason: replaced };
133	    }
134	    return {};
135	  }
136	  const planted = directories.find((dir) => inside(outer, dir));
137	  if (planted) return { reason: `${planted} is a repository nested inside the linked worktree ${outer}` };
138	  let pinned: { gitDir: string; workTree: string } | undefined;
139	  for (const root of files.filter((candidate) => inside(outer, candidate))) {
140	    const dotGit = path.join(root, ".git");
141	    try {
142	      const content = readSmallFile(dotGit, MAX_POINTER_BYTES);
143	      if (content === undefined) return { reason: `${dotGit} is not a plain pointer file` };
144	      const target = parseGitfilePointer(content);
145	      if (target === undefined) return { reason: `${dotGit} is not a well-formed gitdir pointer` };
146	      const admin = fs.realpathSync(path.resolve(root, target));
147	      if (inside(outer, admin)) return { reason: `${dotGit} leads into a repository inside the worktree itself` };
148	      let pointsBack = false;
149	      if (path.basename(path.dirname(admin)) === "worktrees") {
150	        const common = fs.realpathSync(path.dirname(path.dirname(admin)));
151	        if (inside(outer, common)) return { reason: `${dotGit} leads into a repository inside the worktree itself` };
